"""Issue #4965: launched_unconfirmed sorties must not stall past overdue limit."""
from docich.hanjuku_speedrun import hanjuku_chart as chart
from docich.hanjuku_speedrun.hanjuku.state.regions import plan as _plan_region, sorties as _sorties, world as _world
from docich.hanjuku_speedrun.hanjuku.strategy import orders as O


def test_unconfirmed_boss_order_with_verification_unavailable_relaunches():
    # g1190-ch1v4 46-3 / 46-6: A:91632f7b:M085c5c / M0cb1e6 / Mee6da8 sat in
    # orders[step] == 'launched_unconfirmed' after _give_up_source set
    # verification_unavailable=True and never moved to overdue.
    step = 'A:91632f7b:M085c5c'
    launch_tick = 923961
    mem = {
        'chapter': 10,
        'tick': launch_tick + O.MARCH_ARRIVAL_CAP,
        '_records': [],
        'orders': {step: 'launched_unconfirmed'},
        'lost': ['ファルゲ'],
        'captured': ['ピランドリア', 'トルストリア', 'マカリア'],
        'world': {
            'garrison': {'アルマムーン': ['どうし', 'プラリネ']},
            'sorties': {
                step: {
                    'general': 'ガルバンゾー',
                    'source': 'アルマムーン',
                    'target': None,
                    'planned_target': 'ボス',
                    'status': 'launched_unconfirmed',
                    'tick': launch_tick,
                    'verification_reads': 3,
                    'verification_unavailable': True,
                },
            },
            'launched_orders': {
                step: {
                    'step': step,
                    'general': 'ガルバンゾー',
                    'source': 'アルマムーン',
                    'target': 'ボス',
                    'purpose': 'attack',
                },
            },
        },
    }

    O._relaunch_overdue_boss(mem)

    assert _sorties(mem)[step]['status'] == 'overdue'
    assert _plan_region(mem)['orders'][step] == 'pending'
    assert step not in (_world(mem).get('launched_orders') or {})
    assert mem['boss_relaunch'][step] == 1
    assert [r for r in mem['_records'] if r['decision'] == 'boss_sortie_overdue']


def test_unconfirmed_exhausted_boss_step_tracks_parked_and_retries():
    step = 'A:91632f7b:M0cb1e6'
    launch_tick = 1000
    mem = {
        'chapter': 10,
        'tick': launch_tick + O.MARCH_ARRIVAL_CAP,
        '_records': [],
        'orders': {step: 'launched_unconfirmed'},
        'boss_relaunch': {step: O.BOSS_RELAUNCH_LIMIT},
        'boss_step_probe': {step: len(chart.BOSS_CELL_PROBES[10]) - 1},
        'world': {
            'sorties': {
                step: {
                    'general': 'シュガー',
                    'source': 'アルマムーン',
                    'target': None,
                    'planned_target': 'ボス',
                    'status': 'overdue',
                    'tick': launch_tick,
                },
            },
        },
    }

    assert O.parked_boss_steps(mem) == [step]

    mem['tick'] = launch_tick + O.BOSS_STALE_COOLDOWN
    O._relaunch_overdue_boss(mem)

    assert _plan_region(mem)['orders'][step] == 'pending'
    assert mem['boss_relaunch'][step] == 1
    assert [r for r in mem['_records'] if r['decision'] == 'boss_relaunch_stale_retry']


